INSERT INTO research_tests (id, grp, name, symbol, period, trades, pf, t_stat, pos_years, verdict, notes, tested_on) VALUES
('D1-weak-close-hold', 'D', 'Weak RTH close (IBS<0.2) → buy 18:00 reopen → sell 15:55 next session', 'NQ', '2010–2026', 669, 1.49, 2.95, '15/17', 'edge', 'Monotonic in IBS (<0.2 +21.8 pts, 0.2–0.4 +12.2, >0.6 negative); both halves positive per ATR; ES PF 1.36 t 2.49; a 1.5×ATR stop keeps PF 1.38. 41 trades/yr, $28/trade at 1 MNQ, 2022 drawdown −$6k/MNQ.', '2026-10-11'),
('D2-weak-close-rth-only', 'D', 'Same signal, 09:30 → 15:55 only (strictly intraday)', 'NQ', '2010–2026', 669, 1.31, 1.96, NULL, 'weak', 'Half the edge (0.060 ATR vs 0.128); the overnight leg carries 0.069 ATR.', '2026-10-11'),
('D3-daily-sweep', 'D', 'Sweep: 7 families × ~70 variants (IBS × holds 1–3 / exit-on-strength, RSI(2), streaks, fear days, FOMC/NFP drift+fade, NQ/ES spread, Donchian-20/SMA trend)', 'NQ+ES', '2010–2026', NULL, NULL, NULL, NULL, 'edge', '21 survive t≥2.5, PF≥1.2, both halves>0, ES confirm — all long mean reversion after weakness (+ donchian20 hold5). Best ibs<0.1 exit-on-strength PF 3.12 15/17 yrs; shorts, event rules, spread: nothing. Multi-session holds are illegal on Tradeify (flat by 16:45).', '2026-10-11'),
('D4-gap-and-go-vix', 'I', 'Gap-and-go (|gap|≥0.2 ATR, holding at 09:45, with the gap to the close, stop at the open), by VIX regime', 'NQ', '2013–2026', 530, 1.31, NULL, '8/14', 'weak', 'Gate on (VIX≥18 | rose>10% | pct≥0.66) PF 1.31 +6.8 pts; gate off PF 0.85. Tick replay trend_gap_go_20: PF 3.2 on VIX≥20 days, 6/6 years 2021–26.', '2026-10-11'),
('V1-vix-regime-weakness', 'V', 'Weakness holds conditioned on the prior close VIX (level / 5-day rise / 252-day percentile / VIX3M term structure)', 'NQ+ES', '2010–2026', 983, 1.51, 3.40, '14/17', 'edge', 'ibs<0.3: VIX<15 +$0.4, 15–20 +$9, 20–30 +$32, >30 +$81 per MNQ; rsi2<20 & VIX≥20 221 trades +$105 PF 2.09 14/16 yrs (ES 1.87); any weakness & gate 681 trades +$45 PF 1.51 t 3.4 worst yr −$257. The beta hold is NEGATIVE in deep backwardation. SPY drawdown / HYG−TLT say the same.', '2026-10-11'),
('V2-vix-intraday', 'V', 'Intraday families split by VIX regime (fleet tick replay 2024–26; 16-year bar tests ATR-ORB and Keltner-20 ride)', 'NQ', '2013–2026', NULL, NULL, NULL, NULL, 'no edge', 'The fear regime makes breakouts less losing, not winning: ORB PF 0.36→0.81, trend 0.33→0.56, mtf ≤0.54, lv_conf flat; no positive VIX bucket for ATR-ORB or Keltner over 16 years. Tick-replay VIX≥20 winners (keltner_ride_20_15m PF 2.15) are 2022 artefacts.', '2026-10-11'),
('V3-day-only-weakness-vix', 'V', 'Day-only weakness hold (09:30 → 15:55 after a weak close) with VIX gates', 'NQ', '2010–2026', 532, 1.54, 3.08, '13/16', 'edge', 'any weakness & VIX≥20 +$50/MNQ PF 1.54; rsi2<20 & VIX≥20 +$71 PF 1.77 11/16 yrs. ≈ two-thirds of the 18:00→15:55 form; the fallback if Tradeify refuses 18:00 entries. ES day-only is weak.', '2026-10-11'),
('V4-pre-fomc-drift', 'V', 'Enter the evening before an FOMC decision, exit 15:55 on the day (137 decisions 2010–26 loaded into calendar)', 'NQ', '2010–2026', 125, 1.55, 1.43, '12/17', 'weak', '+$41/MNQ per hold; the session AFTER the decision is −$42 (PF 0.66). NFP eves neutral.', '2026-10-11'),
('I1-ml-15m', 'I', 'Walk-forward LightGBM, 69 indicators on 15m bars, targets 15m / 1h / 2h / to-close / next-day', 'NQ', '2013–2026', NULL, 0.93, NULL, '12/14', 'no edge', 'OOS Spearman IC +0.02..0.04 (real, 12/14 years) but gross 0.05–0.10 ATR vs 0.2 ATR cost; top-2% subset PF 1.03–1.06; passive limit fills recover almost nothing (PF 1.02→1.03). Daily-horizon models unstable by year.', '2026-10-11'),
('I2-day-type-0945', 'I', 'Day-type prediction at 09:45 (range/ATR, ORB-5 follow-through, trend efficiency, close position)', 'NQ', '2013–2026', NULL, NULL, NULL, '13/13', 'no edge', 'A real SIGNAL (range IC 0.51 every year; ORB follow-through IC 0.17 every year; direction IC 0.09) that no strategy converts: ATR-ORB loses on predicted big days (PF 0.8–0.9), fading them loses too, the mid-range quintile is a +1–8 pt tilt (9/14 yrs), 10:00 follow-through to the close is 2019+-only.', '2026-10-11'),
('I3-ema-pullback-structure', 'I', 'EMA20/50 and EMA50/200 pullback in a stacked regime, 5m/15m, ATR stops, 2R or close', 'NQ', '2010–2026', 4175, 1.01, NULL, '9/14', 'no edge', 'Gross +0.4–0.6 pts/trade on 5m vs 2.4 cost; 15m longs PF 1.2–1.3 carried by 2022; shorts nothing. High-volume pullback bars and the first hour win only in 2024–25. Fleet ema_pullback__rg_trend PF 0.55; only __lv_conf (level confluence) is PF 1.60 in every replayed year.', '2026-10-11'),
('I4-passive-entries', 'I', 'Limit entry at signal −1 tick (fill only if traded through within 5 min) for the lv_conf family', 'NQ', '2022–2026', 4222, 0.35, NULL, '0/4', 'no edge', 'Fills 78–85% but the unfilled 15–20% carry more than all the profit: market PF 1.43 → passive PF 0.35. Momentum entries must be taken at market.', '2026-10-11'),
('M1-multi-asset-sweep', 'M', 'Daily sweep on 15 futures (yfinance continuous: NQ ES YM RTY GC SI HG CL NG ZN ZB 6E 6J ZC ZS) + 18 ETFs (no roll gaps): weakness-long, strength-short, own-vol fear, VIX gate, 20-day TSMOM both sides', 'multi', '2009–2026', NULL, NULL, NULL, NULL, 'no edge', 'The weakness-long edge exists ONLY in US equity indices (NQ t 3.9–4.2, QQQ/IWM/SPY c→c with the VIX gate 15–18/18 yrs; ES weaker; YM/RTY marginal); commodities, rates, FX and grains are negative on it. Shorts, TSMOM and own-vol gates show nothing once costs are subtracted correctly — a first run ADDED the cost on shorts and produced t 7–9 "edges" on bonds/grains/silver that the unconditional baseline exposed (futures also carry roll-gap drift: ZN −3.4 ATR/yr of close→open gaps). No second, uncorrelated book is available from daily price action; width must come from somewhere else (data, not instruments).', '2026-10-11'),
('X1-conditional-exits', 'X', 'Exits on the gated book: take at noon / 14:00 / 09:30 gap if up ≥ x ATR, cut at noon if down, +1.5 ATR target, trail — vs hold to 15:55', 'NQ', '2013–2026', 816, 1.52, NULL, '13/14', 'no edge', 'Hold-to-close is best or tied in every case (avg $54, PF 1.52, maxDD −$4,496); every early take or stop lowers avg and raises the worst year. The exit stays 15:55.', '2026-10-11'),
('X2-earnings-nights', 'X', 'Hold P&L when a top-10 NQ weight reports after the close (530 dates 2010–26, yfinance)', 'NQ', '2010–2026', 239, 1.41, NULL, '14/17', 'weak', 'Gated book on earnings nights +$38/MNQ PF 1.41 vs +$48 PF 1.54 otherwise — mild degradation, not a reason to skip; size down if anything.', '2026-10-11'),
('X3-crypto-daily', 'X', 'BTC/ETH daily (yfinance 2014–26): weakness-long, strength-short, own-vol fear, TSMOM, net 0.1% RT', 'crypto', '2014–2026', 500, 1.46, 3.02, '8/12', 'weak', 'BTC long weakness & own-fear PF 1.46 t 3.0 but fading (h1 +0.17, h2 +0.05 ATR); BTC TSMOM long PF 1.31 (bull-era); ETH weaker; shorts negative. A possible crypto-prop sleeve, not a second book.', '2026-10-11'),
('P1-conviction-book', 'P', 'Conviction-sized weakness book (any weakness 1 MNQ, +1 weak close, +1 VIX gate, +1 both), Select Daily 50K, 18:00 → 15:55, in payout_sim with the official Tradeify rules', 'NQ', '2020–2026 test', NULL, NULL, NULL, NULL, 'edge', 'Members chosen on 2010–19, scored on 2020–26, 250-day accounts: eval pass 92% / fail 8% (median 58 days), 1.8 payouts/month, 53% of 2-week windows paid, $1,590/month, blown 28%/yr (7% before the first payout). Bigger stacks are SAFER (edge per day outruns the −$2,000 trail): 1 unit blows 89%/yr. 25K accounts do not work. Flex/Growth (5 winning days) cannot pay biweekly; staggered accounts do not raise cadence; day-only fallback 47%/22%, 40% of windows, $430/month.', '2026-10-11')
